def papers(step):
    rows = [H] + P[step]
    tab('pap%s' % step, rows=rows, caption='Step %s – reference papers: what each paper did for this step, and how its method is similar to (and differs from) what I did.' % step, widths=[1650, 3050, 2700, 2200], size=15, nokeep=True)
